"use client"

import * as React from "react"
import { cn } from "cn"

// NOTE: Update these paths if needed
import "../tokens.css"
import "./aurora.css"

const gradientNames = [
  "aurora",
  "sunrise",
  "sunset",
  "ocean",
  "forest",
  "fire",
  "candy",
  "lavender",
  "mint",
  "peach",
  "midnight",
  "gold",
  "rainbow",
  "cyber",
  "plasma",
  "mono",
] as const

type GradientName = (typeof gradientNames)[number]

type AuroraProps = React.ComponentProps<"div"> & {
  /** The color set. Defaults to `aurora`. */
  gradient?: GradientName
  /** Where the glow shows. `none` fills the whole box. */
  mask?: "corner" | "center" | "top" | "bottom" | "none"
  intensity?: "subtle" | "default" | "strong"
  speed?: "slow" | "default" | "fast"
  /** Set to `false` for a still glow. */
  animated?: boolean
  /** Replaces the rendered element, such as a section. */
  render?: React.ReactElement
}

function Aurora({
  gradient = "aurora",
  mask = "corner",
  intensity = "default",
  speed = "default",
  animated = true,
  className,
  render,
  ...props
}: AuroraProps) {
  const merged = {
    "data-slot": "aurora",
    "data-gradient": gradient === "aurora" ? undefined : gradient,
    "data-mask": mask === "corner" ? undefined : mask,
    "data-intensity": intensity === "default" ? undefined : intensity,
    "data-speed": speed === "default" ? undefined : speed,
    "data-animate": animated ? undefined : "false",
    ...props,
    className: cn("np-aurora", className),
  }

  if (React.isValidElement(render)) {
    const own = render.props as { className?: string }
    return React.cloneElement(render, {
      ...merged,
      ...(render.props as Record<string, unknown>),
      className: cn(merged.className, own.className),
    } as Record<string, unknown>)
  }

  return <div {...merged} />
}

export { Aurora, gradientNames }
export type { AuroraProps, GradientName }

/* nepui — Aurora */

:is(.np-aurora, [data-np-aurora]) {
  --np-aurora-color-1: oklch(0.72 0.14 250);
  --np-aurora-color-2: oklch(0.7 0.18 280);
  --np-aurora-color-3: oklch(0.8 0.12 220);
  --np-aurora-color-4: oklch(0.72 0.2 310);
  --np-aurora-color-5: oklch(0.78 0.13 190);
  --np-aurora-opacity: 0.6;
  --np-aurora-blur: 10px;
  --np-aurora-duration: 60s;
  --np-aurora-mask: radial-gradient(
    ellipse at 100% 0%,
    #000 10%,
    transparent 70%
  );

  position: relative;
  isolation: isolate;
  overflow: hidden;
  background: var(--np-background);
  color: var(--np-foreground);
}

:is(.np-aurora, [data-np-aurora])::before {
  content: "";
  position: absolute;
  inset: calc(var(--np-aurora-blur) * -1);
  z-index: -1;
  pointer-events: none;
  background-image:
    repeating-linear-gradient(
      100deg,
      var(--np-background) 0%,
      var(--np-background) 7%,
      transparent 10%,
      transparent 12%,
      var(--np-background) 16%
    ),
    repeating-linear-gradient(
      100deg,
      var(--np-aurora-color-1) 10%,
      var(--np-aurora-color-2) 15%,
      var(--np-aurora-color-3) 20%,
      var(--np-aurora-color-4) 25%,
      var(--np-aurora-color-5) 30%
    );
  background-size: 300% 200%;
  background-position:
    50% 50%,
    50% 50%;
  filter: blur(var(--np-aurora-blur));
  opacity: var(--np-aurora-opacity);
  -webkit-mask-image: var(--np-aurora-mask);
  mask-image: var(--np-aurora-mask);
  animation: np-aurora-flow var(--np-aurora-duration) linear infinite;
  will-change: background-position;
}

:is(.np-aurora, [data-np-aurora])[data-gradient="sunrise"] {
  --np-aurora-color-1: oklch(0.7 0.19 295);
  --np-aurora-color-2: oklch(0.72 0.2 320);
  --np-aurora-color-3: oklch(0.72 0.21 350);
  --np-aurora-color-4: oklch(0.76 0.19 30);
