}

:is(.np-aurora, [data-np-aurora])[data-mask="bottom"] {
  --np-aurora-mask: linear-gradient(to top, #000 0%, transparent 80%);
}

:is(.np-aurora, [data-np-aurora])[data-mask="none"] {
  --np-aurora-mask: none;
}

:is(.np-aurora, [data-np-aurora])[data-intensity="subtle"] {
  --np-aurora-opacity: 0.35;
}

:is(.np-aurora, [data-np-aurora])[data-intensity="strong"] {
  --np-aurora-opacity: 0.9;
}

:is(.np-aurora, [data-np-aurora])[data-speed="slow"] {
  --np-aurora-duration: 120s;
}

:is(.np-aurora, [data-np-aurora])[data-speed="fast"] {
  --np-aurora-duration: 30s;
}

:is(.np-aurora, [data-np-aurora])[data-animate="false"]::before {
  animation: none;
}

@keyframes np-aurora-flow {
  to {
    background-position:
      350% 50%,
      350% 50%;
  }
}

@media (prefers-reduced-motion: reduce) {
  :is(.np-aurora, [data-np-aurora])::before {
    animation: none;
  }
}
